import { useEffect, useRef, useState } from 'preact/hooks';
import { VISUAL_STYLES, cleanPrompt } from '../../shared/visual-styles';
import { api } from './api';
import { say, visualsOn } from './state';
import { Spinner } from './brand';
import { Dialog, when } from './ui';

type Visual = { id: string; style: string; prompt: string | null; created_at: number; user_email: string | null; image: string; source: string };

/**
 * Architectural images from the 3D model, generated by Cloudinary: a snapshot of the current view is set in a scene
 * (garden, street, panorama) or laid on a presentation board. Generation happens on Cloudinary and can take a minute,
 * so each image retries until it is ready.
 */
export function VisualsDialog({ projectId, snapshot, onShow3D, onClose }: {
  projectId: string; snapshot: (() => Promise<Blob> | null) | null; onShow3D(): void; onClose(): void;
}) {
  const [list, setList] = useState<Visual[] | null>(null);
  const [style, setStyle] = useState('site');
  const [prompt, setPrompt] = useState('');
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState('');
  const [preview, setPreview] = useState<string | null>(null);
  useEffect(() => {
    api<{ visuals: Visual[] }>(`/projects/${projectId}/visuals`).then((d) => setList(d.visuals)).catch((e) => { setErr(e.message); setList([]); });
    let url: string | null = null;
    snapshot?.()?.then((b) => { url = URL.createObjectURL(b); setPreview(url); }).catch(() => {});
    return () => { if (url) URL.revokeObjectURL(url); };
  }, [projectId]);

  async function generate(e: Event) {
    e.preventDefault();
    setErr('');
    const custom = style === 'custom' ? cleanPrompt(prompt) : '';
    if (style === 'custom' && custom.length < 3) return setErr('Describe the scene in a few words, e.g. "pine forest clearing in winter".');
    const shot = snapshot?.();
    if (!shot) return setErr('Open the 3D view and frame the model first.');
    setBusy(true);
    try {
      const body = await shot;
      const d = await api<{ visual: Visual }>(`/projects/${projectId}/visuals`, { body, headers: { 'content-type': 'image/png', 'x-style': style, ...(custom ? { 'x-prompt': encodeURIComponent(custom) } : {}) } });
      setList((l) => [d.visual, ...(l ?? [])]);
      say('Image requested. It appears here when Cloudinary has generated it.');
    } catch (e) { setErr((e as Error).message); }
    finally { setBusy(false); }
  }
  const remove = async (id: string) => {
    try { await api(`/projects/${projectId}/visuals/${id}`, { method: 'DELETE' }); setList((l) => l?.filter((v) => v.id !== id) ?? null); say('Image removed'); }
    catch (e) { setErr((e as Error).message); }
  };
  const label = (k: string) => VISUAL_STYLES.find((s) => s.key === k)?.label ?? 'Custom scene';

  return (
    <Dialog title="Architectural images" onClose={onClose} wide>
      <div class="dlg-body vis">
        {!visualsOn.value ? (
          <div class="vis-off">
            <p><b>Image generation isn't set up on this server.</b></p>
            <p class="muted small">It uses Cloudinary. An administrator sets <code>CLOUDINARY_CLOUD_NAME</code> and <code>CLOUDINARY_API_KEY</code> in the Worker's variables and <code>CLOUDINARY_API_SECRET</code> as a secret, with generative AI enabled on the Cloudinary account.</p>
          </div>
        ) : (
          <form class="vis-new" onSubmit={generate}>
            <figure class="vis-shot">
              {preview ? <img src={preview} alt="Snapshot of the current 3D view" /> : <div class="vis-empty"><p class="small muted">No 3D view on screen.</p><button type="button" class="btn ghost sm" onClick={onShow3D}>Open 3D</button></div>}
              <figcaption class="small muted">The current 3D view is used. Orbit and zoom to frame it first.</figcaption>
            </figure>
            <fieldset class="vis-styles">
              <legend class="small">Style</legend>
              {[...VISUAL_STYLES, { key: 'custom', label: 'Your own scene', detail: 'Describe the surroundings', generative: true, prompt: null }].map((s) => (
                <label key={s.key} class={`vis-style${style === s.key ? ' on' : ''}`}>
                  <input type="radio" name="vstyle" value={s.key} checked={style === s.key} onChange={() => setStyle(s.key)} />
                  <span><b>{s.label}</b><span class="small muted">{s.detail}{s.generative ? ' · generative' : ''}</span></span>
                </label>
              ))}
              {style === 'custom' && (
                <input class="vis-prompt" maxLength={160} placeholder="e.g. pine forest clearing in winter, low sun" value={prompt} onInput={(e) => setPrompt(e.currentTarget.value)} aria-label="Scene description" />
              )}
              <p class="err" role="alert">{err}</p>
              <button class="btn sm" disabled={busy || !preview}>{busy ? <><Spinner size={14} label={null} />Uploading…</> : 'Generate image'}</button>
              <p class="hint">Generative styles use Cloudinary AI credits and can take a minute. Up to 20 images a day.</p>
            </fieldset>
          </form>
        )}
        <h3 class="vis-h">In this project</h3>
        {list === null ? <Spinner size={24} label="Loading images" />
          : !list.length ? <p class="muted small">No images yet.</p>
          : <ul class="vis-grid">{list.map((v) => <VisualCard key={v.id} v={v} label={label(v.style)} onRemove={() => remove(v.id)} />)}</ul>}
      </div>
    </Dialog>
  );
}

/** One generated image; until Cloudinary has made it, the request fails and is retried every few seconds. */
function VisualCard({ v, label, onRemove }: { v: Visual; label: string; onRemove(): void }) {
  const [src, setSrc] = useState(v.image);
  const [ready, setReady] = useState(false);
  const [gaveUp, setGaveUp] = useState(false);
  const tries = useRef(0), timer = useRef(0);
  useEffect(() => () => clearTimeout(timer.current), []);
  const retry = () => {
    if (++tries.current > 36) return setGaveUp(true); // about 3 minutes
    timer.current = window.setTimeout(() => setSrc(`${v.image}?r=${tries.current}`), 5000);
  };
  return (
    <li class="vis-card">
      <div class="vis-img">
        <img src={src} alt={`${label} image generated from the model${v.prompt ? `: ${v.prompt}` : ''}`} loading="lazy" onLoad={() => setReady(true)} onError={retry} style={{ opacity: ready ? 1 : 0 }} />
        {!ready && <div class="vis-wait">{gaveUp ? <span class="small">Not ready. <button class="link small" onClick={() => { tries.current = 0; setGaveUp(false); setSrc(`${v.image}?r=${Date.now()}`); }}>Try again</button></span> : <><Spinner size={20} label={null} /><span class="small">Generating…</span></>}</div>}
      </div>
      <div class="vis-meta">
        <b>{label}</b><span class="small muted">{when(v.created_at)}{v.user_email ? ` · ${v.user_email}` : ''}</span>
        <span class="vis-links small">
          <a class="link" href={v.image} target="_blank" rel="noopener">Open</a>
          <a class="link" href={v.source} target="_blank" rel="noopener">Snapshot</a>
          <button type="button" class="link small danger" onClick={onRemove}>Remove</button>
        </span>
      </div>
    </li>
  );
}
